52	/// An immutable vector of `T` with `O(1)` copies and structural sharing.
53	///
54	/// Mirrors `immer::vector<T>`: mutating operations consume `&self` and return a
55	/// brand-new value, leaving the receiver untouched.
56	pub struct Vector<T> {
57	    /// Total number of elements, trie plus tail.
58	    size: usize,
59	    /// Index bits consumed at the root. Leaves sit at level 0, so the trie's
60	    /// depth is `shift / BITS + 1`.
61	    shift: u32,
62	    /// Root of the trie; always an inner node, empty when the trie is empty.
63	    root: Rc<Node<T>>,
64	    /// Trailing chunk of up to `BRANCHING` elements.
65	    tail: Rc<Vec<T>>,
66	}
67	
68	impl<T> Vector<T> {
69	    /// Creates an empty vector. Equivalent to `immer::vector<T>{}`.
70	    pub fn new() -> Vector<T> {
71	        Vector {
72	            size: 0,
73	            shift: BITS,
74	            root: Node::empty_inner(),
75	            tail: Rc::new(Vec::new()),
76	        }
77	    }
78	
79	    /// Number of elements, matching `immer::vector::size()`.
80	    pub fn size(&self) -> usize {
81	        self.size
82	    }
83	
84	    /// Number of elements. Rust-idiomatic alias for [`Vector::size`].
85	    pub fn len(&self) -> usize {
86	        self.size
87	    }
88	
89	    /// Whether the vector has no elements.
90	    pub fn is_empty(&self) -> bool {
91	        self.size == 0
92	    }
93	
94	    /// Index of the first element held in the tail rather than in the trie.
95	    ///
96	    /// Equal to `size` rounded *down* to a multiple of `BRANCHING`, except that a
97	    /// vector of exactly `BRANCHING` elements still keeps them all in the tail
98	    /// (the trie only gains a leaf once a 33rd element arrives). Expressing it as
99	    /// `((size - 1) >> BITS) << BITS` gets both cases with one formula.
100	    pub(super) fn tail_offset(&self) -> usize {
101	        if self.size < BRANCHING {
102	            0
103	        } else {
104	            ((self.size - 1) >> BITS) << BITS
105	        }
106	    }
107	
108	    /// The trailing chunk.
109	    pub(super) fn tail_slice(&self) -> &[T] {
110	        &self.tail
111	    }
112	
113	    /// The trie root.
114	    pub(super) fn root(&self) -> &Rc<Node<T>> {
115	        &self.root
116	    }
117	
118	    /// Returns the 32-element chunk containing index `i`.
119	    ///
120	    /// `i` must be `< size`. Routing is pure radix arithmetic: peel `BITS` bits
121	    /// off the index at every level, most significant digit first.
122	    fn leaf_for(&self, i: usize) -> &[T] {
123	        debug_assert!(i < self.size);
124	        if i >= self.tail_offset() {
125	            return &self.tail;
126	        }
127	        let mut node: &Node<T> = &self.root;
128	        let mut level = self.shift;
129	        while level > 0 {
130	            node = &node.children()[(i >> level) & MASK];
131	            level -= BITS;
132	        }
133	        node.elems()
134	    }
135	
136	    /// Returns a reference to the element at `i`, or `None` if out of bounds.
137	    ///
138	    /// The checked counterpart to [`Index`]; `immer::vector` has no equivalent,
139	    /// since C++'s `operator[]` on an out-of-range index is undefined behaviour.
140	    pub fn get(&self, i: usize) -> Option<&T> {
141	        if i >= self.size {
142	            None
143	        } else {
144	            Some(&self.leaf_for(i)[i & MASK])
145	        }
146	    }
147	
148	    /// First element, or `None` when empty.
149	    pub fn front(&self) -> Option<&T> {
150	        self.get(0)
151	    }
152	
153	    /// Last element, or `None` when empty.
154	    pub fn back(&self) -> Option<&T> {
155	        if self.size == 0 {
156	            None
157	        } else {
158	            self.get(self.size - 1)
159	        }
160	    }
161	
162	    /// Borrowing forward iterator, in index order.
163	    pub fn iter(&self) -> Iter<'_, T> {
164	        Iter::new(self)
165	    }
166	}
