168	impl<T: Clone> Vector<T> {
169	    /// Returns a new vector with `value` appended; `self` is unchanged.
170	    ///
171	    /// Three cases, in order of frequency:
172	    ///
173	    /// 1. **Tail has room** (31 of every 32 calls) — copy the tail chunk, push
174	    ///    onto the copy, share the whole trie.
175	    /// 2. **Tail is full, trie has room** — freeze the tail into a leaf and
176	    ///    graft it into the trie, copying only the nodes along its path; the new
177	    ///    value starts a fresh one-element tail.
178	    /// 3. **Tail is full and the trie is full** — grow the trie one level: a new
179	    ///    root whose first child is the old root and whose second child is a
180	    ///    fresh spine down to the frozen tail.
181	    pub fn push_back(&self, value: T) -> Vector<T> {
182	        if self.tail.len() < BRANCHING {
183	            // Case 1: room in the tail.
184	            let mut tail = (*self.tail).clone();
185	            tail.push(value);
186	            return Vector {
187	                size: self.size + 1,
188	                shift: self.shift,
189	                root: Rc::clone(&self.root),
190	                tail: Rc::new(tail),
191	            };
192	        }
193	
194	        let leaf = Rc::new(Node::Leaf((*self.tail).clone()));
195	        let (root, shift) = if self.is_root_full() {
196	            // Case 3: deepen the trie.
197	            let root = Rc::new(Node::Inner(vec![
198	                Rc::clone(&self.root),
199	                new_path(self.shift, leaf),
200	            ]));
201	            (root, self.shift + BITS)
202	        } else {
203	            // Case 2: graft the frozen tail into the existing trie.
204	            (push_leaf(self.size, self.shift, &self.root, leaf), self.shift)
205	        };
206	
207	        Vector {
208	            size: self.size + 1,
209	            shift,
210	            root,
211	            tail: Rc::new(vec![value]),
212	        }
213	    }
214	
215	    /// Whether the trie cannot accept another leaf at the current depth.
216	    ///
217	    /// A root at `shift` addresses `1 << shift` leaf slots — i.e. `BRANCHING <<
218	    /// shift` elements. `size >> BITS` is the number of leaves the trie would
219	    /// hold after the full tail is grafted in, minus nothing: when that count
220	    /// exceeds the addressable slots, the root must grow. Only called with a
221	    /// full tail, so `size` is a positive multiple of `BRANCHING`.
222	    fn is_root_full(&self) -> bool {
223	        (self.size >> BITS) > (1usize << self.shift)
224	    }
225	
226	    /// Returns a new vector with index `i` replaced by `value`.
227	    ///
228	    /// Copies only the `O(log32 n)` nodes on the path to `i`; `self` is
229	    /// unchanged. Returns `None` if `i` is out of bounds.
230	    pub fn update(&self, i: usize, value: T) -> Option<Vector<T>> {
231	        if i >= self.size {
232	            return None;
233	        }
234	        if i >= self.tail_offset() {
235	            let mut tail = (*self.tail).clone();
236	            tail[i & MASK] = value;
237	            return Some(Vector {
238	                size: self.size,
239	                shift: self.shift,
240	                root: Rc::clone(&self.root),
241	                tail: Rc::new(tail),
242	            });
243	        }
244	        Some(Vector {
245	            size: self.size,
246	            shift: self.shift,
247	            root: update_path(i, self.shift, &self.root, value),
248	            tail: Rc::clone(&self.tail),
249	        })
250	    }
251	}
252	
253	/// Grafts a full `leaf` into the trie rooted at `parent`.
254	///
255	/// `size` is the element count *before* the push, so `size - 1` is the index of
256	/// the last element of the leaf being inserted, and its radix digits spell out
257	/// where the leaf belongs. At each level the digit either selects an existing
258	/// child to recurse into or points one past the last child, meaning a fresh
259	/// spine has to be created there.
260	fn push_leaf<T>(
261	    size: usize,
262	    level: u32,
263	    parent: &Rc<Node<T>>,
264	    leaf: Rc<Node<T>>,
265	) -> Rc<Node<T>> {
266	    let subidx = ((size - 1) >> level) & MASK;
267	    let children = parent.children();
268	    // The trie fills left-to-right, so the digit either selects a child that
269	    // already exists or points at the very next slot. Note that a node may well
270	    // be at full width (32 children) and still be the right place to recurse
271	    // into: its last child can have room inside it.
272	    debug_assert!(subidx <= children.len(), "the trie fills left-to-right with no gaps");
273	    debug_assert!(
274	        subidx < BRANCHING && children.len() <= BRANCHING,
275	        "a node never exceeds its branching factor"
276	    );
277	
278	    let insert = if level == BITS {
279	        // One level above the leaves: this is where the leaf lands.
280	        leaf
281	    } else if subidx < children.len() {
282	        push_leaf(size, level - BITS, &children[subidx], leaf)
283	    } else {
284	        new_path(level - BITS, leaf)
285	    };
286	
287	    // Copy this node (cheap: a vector of at most 32 reference-count bumps) and
288	    // splice in the rebuilt child. Every sibling subtree stays shared.
289	    let mut copy = children.clone();
290	    if subidx < copy.len() {
291	        copy[subidx] = insert;
292	    } else {
293	        copy.push(insert);
294	    }
295	    Rc::new(Node::Inner(copy))
296	}
297	
298	/// Rebuilds the path to index `i`, replacing that element with `value`.
299	fn update_path<T: Clone>(i: usize, level: u32, node: &Rc<Node<T>>, value: T) -> Rc<Node<T>> {
300	    if level == 0 {
301	        let mut elems = node.elems().to_vec();
302	        elems[i & MASK] = value;
303	        return Rc::new(Node::Leaf(elems));
304	    }
305	    let children = node.children();
306	    let subidx = (i >> level) & MASK;
307	    let mut copy = children.clone();
308	    copy[subidx] = update_path(i, level - BITS, &children[subidx], value);
309	    Rc::new(Node::Inner(copy))
310	}
