312	impl<T> Clone for Vector<T> {
313	    /// `O(1)`: copies the two handles and bumps their reference counts, exactly
314	    /// like copying an `immer::vector`.
315	    fn clone(&self) -> Vector<T> {
316	        Vector {
317	            size: self.size,
318	            shift: self.shift,
319	            root: Rc::clone(&self.root),
320	            tail: Rc::clone(&self.tail),
321	        }
322	    }
323	}
324	
325	impl<T> Default for Vector<T> {
326	    fn default() -> Vector<T> {
327	        Vector::new()
328	    }
329	}
