331	impl<T> Index<usize> for Vector<T> {
332	    type Output = T;
333	
334	    /// Element access, matching `immer::vector::operator[]`.
335	    ///
336	    /// # Panics
337	    ///
338	    /// Panics if `i >= size()`. (C++ leaves this undefined; Rust checks.)
339	    fn index(&self, i: usize) -> &T {
340	        match self.get(i) {
341	            Some(value) => value,
342	            None => panic!(
343	                "index out of bounds: the len is {} but the index is {}",
344	                self.size, i
345	            ),
346	        }
347	    }
348	}
