359	impl<T: Clone> IntoIterator for Vector<T> {
360	    type Item = T;
361	    type IntoIter = IntoIter<T>;
362	
363	    fn into_iter(self) -> IntoIter<T> {
364	        IntoIter::new(self)
365	    }
366	}
