368	impl<T: Clone> FromIterator<T> for Vector<T> {
369	    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Vector<T> {
370	        let mut vector = Vector::new();
371	        for item in iter {
372	            vector = vector.push_back(item);
373	        }
374	        vector
375	    }
376	}
