378	impl<T: PartialEq> PartialEq for Vector<T> {
379	    fn eq(&self, other: &Vector<T>) -> bool {
380	        self.size == other.size && self.iter().zip(other.iter()).all(|(a, b)| a == b)
381	    }
382	}
