396	    /// Builds `0..n` and checks size, indexing and iteration against `Vec`.
397	    fn check_range(n: usize) {
398	        let mut v: Vector<usize> = Vector::new();
399	        for i in 0..n {
400	            v = v.push_back(i);
401	        }
402	        assert_eq!(v.size(), n, "size for n = {}", n);
403	        for i in 0..n {
404	            assert_eq!(v[i], i, "index {} for n = {}", i, n);
405	        }
406	        assert_eq!(v.get(n), None);
407	        let collected: Vec<usize> = v.iter().copied().collect();
408	        assert_eq!(collected, (0..n).collect::<Vec<_>>(), "iteration for n = {}", n);
409	        assert_eq!(collected.len(), n);
410	    }
