453	    #[test]
454	    fn a_large_trie_agrees_with_a_plain_vec_element_by_element() {
455	        // The C++ program only prints sums, which are order-insensitive, so
456	        // element *placement* has to be checked directly: index order and
457	        // iteration order must both match a std Vec exactly.
458	        const N: usize = 40_000;
459	        let reference: Vec<usize> = (0..N).map(|i| i * 7 + 1).collect();
460	        let mut v: Vector<usize> = Vector::new();
461	        for value in &reference {
462	            v = v.push_back(*value);
463	        }
464	        assert_eq!(v.size(), N);
465	        for (i, expected) in reference.iter().enumerate() {
466	            assert_eq!(v[i], *expected, "index {}", i);
467	        }
468	        assert!(v.iter().eq(reference.iter()), "iteration order");
469	    }
