471	    #[test]
472	    fn push_back_leaves_the_source_untouched() {
473	        // Persistence: keep every intermediate version alive across a depth
474	        // increase and re-verify all of them afterwards.
475	        let mut versions = vec![Vector::<usize>::new()];
476	        for i in 0..1100 {
477	            let next = versions[versions.len() - 1].push_back(i);
478	            versions.push(next);
479	        }
480	        for (n, v) in versions.iter().enumerate() {
481	            assert_eq!(v.size(), n);
482	            assert_eq!(v.iter().copied().collect::<Vec<_>>(), (0..n).collect::<Vec<_>>());
