550	    fn structural_sharing_actually_shares() {
551	        // A push must not deep-copy the trie: the untouched left subtree of the
552	        // root has to be the very same allocation in both versions.
553	        let a: Vector<i32> = (0..2000).collect();
554	        let b = a.push_back(2000);
555	        let left_a = Rc::clone(&a.root().children()[0]);
