561	    fn the_trie_only_deepens_when_the_root_fills_up() {
562	        // A root at shift 5 addresses 32 leaves = 1024 trie elements, and the
563	        // tail holds 32 more, so element 1057 is the first that cannot fit.
564	        let mut v: Vector<usize> = Vector::new();
565	        for i in 0..1056 {
566	            v = v.push_back(i);
567	        }
568	        assert_eq!(v.shift, BITS, "still one level of inner nodes at n = 1056");
569	        assert_eq!(v.root.children().len(), BRANCHING);
570	        assert_eq!(v.tail.len(), BRANCHING);
