580	    #[test]
581	    fn the_tail_holds_the_first_thirty_two_elements() {
582	        // Until a 33rd element arrives the trie stays empty: that is what makes
583	        // the first 32 pushes pure tail copies.
584	        let mut v: Vector<usize> = Vector::new();
585	        for i in 0..32 {
586	            v = v.push_back(i);
587	        }
588	        assert_eq!(v.tail_offset(), 0);
589	        assert_eq!(v.tail.len(), 32);
590	        assert!(v.root.children().is_empty());
591	
592	        v = v.push_back(32);
593	        assert_eq!(v.tail_offset(), 32);
594	        assert_eq!(v.tail.len(), 1);
595	        assert_eq!(v.root.children().len(), 1);
596	    }
597	}
