1	//! Forward iteration over a persistent vector.
2	//!
3	//! The naive way to iterate a vector trie is to call the indexing routine once
4	//! per element, which re-descends the trie every time: `O(n log n)` overall.
5	//! [`Iter`] instead keeps the current root-to-leaf path on an explicit stack and
6	//! walks it like an odometer, so each `next()` is amortised `O(1)` and a full
7	//! traversal is `O(n)` — the same shape as the chunked iterators the C++
8	//! original uses.
9	
10	use std::rc::Rc;
11	
12	use super::node::Node;
13	use super::vector::Vector;
14	
15	/// Borrowing forward iterator over the elements of a [`Vector`].
16	///
17	/// Created by [`Vector::iter`], or by `for x in &vector`.
18	pub struct Iter<'a, T> {
19	    /// The inner nodes on the path to `leaf`, each paired with the index of the
20	    /// child *after* the one we descended into.
21	    stack: Vec<(&'a [Rc<Node<T>>], usize)>,
22	    /// The chunk currently being handed out (a trie leaf, or the tail).
23	    leaf: &'a [T],
24	    /// How far into `leaf` we are.
25	    pos: usize,
26	    /// The vector's trailing chunk, visited once the trie is exhausted.
27	    tail: &'a [T],
28	    /// Whether `leaf` is already the tail.
29	    in_tail: bool,
30	    /// Total elements not yet yielded; drives `size_hint`.
31	    left: usize,
32	}
33	
34	impl<'a, T> Iter<'a, T> {
35	    pub(super) fn new(vector: &'a Vector<T>) -> Iter<'a, T> {
36	        let mut iter = Iter {
37	            stack: Vec::new(),
38	            leaf: &[],
39	            pos: 0,
40	            tail: vector.tail_slice(),
41	            in_tail: false,
42	            left: vector.size(),
43	        };
44	        if vector.tail_offset() > 0 {
45	            // The trie holds elements: prime `leaf` with its leftmost chunk.
46	            iter.descend(vector.root());
47	        } else {
48	            // Everything the vector has (if anything) lives in the tail.
49	            iter.enter_tail();
50	        }
51	        iter
52	    }
53	
54	    /// Descends from `node` to its leftmost leaf, recording the path so
55	    /// [`Iter::advance_chunk`] can resume from it.
56	    fn descend(&mut self, node: &'a Rc<Node<T>>) {
57	        let mut node: &'a Node<T> = node;
58	        while !node.is_leaf() {
59	            let children = node.children();
60	            debug_assert!(!children.is_empty(), "populated subtrees are never empty");
61	            self.stack.push((children, 1));
62	            node = &children[0];
63	        }
64	        self.leaf = node.elems();
65	        self.pos = 0;
66	    }
67	
68	    /// Switches the iterator over to the tail chunk.
69	    fn enter_tail(&mut self) {
70	        self.in_tail = true;
71	        self.leaf = self.tail;
72	        self.pos = 0;
73	    }
74	
75	    /// Moves to the next chunk once the current one is used up.
76	    fn advance_chunk(&mut self) {
77	        if self.in_tail {
78	            // Nothing follows the tail.
79	            self.leaf = &[];
80	            self.pos = 0;
81	            return;
82	        }
83	        // Odometer step: unwind to the deepest level that still has an
84	        // unvisited child, then take that subtree's leftmost leaf.
85	        while let Some((children, next)) = self.stack.pop() {
86	            if next < children.len() {
87	                self.stack.push((children, next + 1));
88	                let child = &children[next];
89	                self.descend(child);
90	                return;
91	            }
92	        }
93	        // The trie is exhausted; the tail is what remains.
94	        self.enter_tail();
95	    }
96	}
97	
98	impl<'a, T> Iterator for Iter<'a, T> {
99	    type Item = &'a T;
100	
101	    fn next(&mut self) -> Option<&'a T> {
102	        if self.left == 0 {
103	            return None;
104	        }
105	        while self.pos >= self.leaf.len() {
106	            self.advance_chunk();
107	            if self.leaf.is_empty() {
108	                // Unreachable while `left > 0`: the size and the structure agree.
109	                return None;
110	            }
111	        }
112	        let item = &self.leaf[self.pos];
113	        self.pos += 1;
114	        self.left -= 1;
115	        Some(item)
116	    }
117	
118	    fn size_hint(&self) -> (usize, Option<usize>) {
119	        (self.left, Some(self.left))
120	    }
121	}
122	
123	impl<'a, T> ExactSizeIterator for Iter<'a, T> {
124	    fn len(&self) -> usize {
125	        self.left
126	    }
127	}
128	
129	impl<'a, T> std::iter::FusedIterator for Iter<'a, T> {}
