131	/// Consuming iterator, yielding clones of the elements in order.
132	///
133	/// A persistent vector's storage may still be shared with other versions, so the
134	/// elements cannot be moved out; cloning is the faithful behaviour.
135	pub struct IntoIter<T> {
136	    vector: Vector<T>,
137	    index: usize,
138	}
139	
140	impl<T> IntoIter<T> {
141	    pub(super) fn new(vector: Vector<T>) -> IntoIter<T> {
142	        IntoIter { vector, index: 0 }
143	    }
144	}
145	
146	impl<T: Clone> Iterator for IntoIter<T> {
147	    type Item = T;
148	
149	    fn next(&mut self) -> Option<T> {
150	        let item = self.vector.get(self.index)?.clone();
151	        self.index += 1;
152	        Some(item)
153	    }
154	
155	    fn size_hint(&self) -> (usize, Option<usize>) {
156	        let left = self.vector.size() - self.index;
157	        (left, Some(left))
158	    }
159	}
160	
161	impl<T: Clone> ExactSizeIterator for IntoIter<T> {}
